from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Mapping


def _dedupe_strings(values: tuple[str, ...]) -> tuple[str, ...]:
    seen: set[str] = set()
    ordered: list[str] = []
    for value in values:
        normalized = value.strip()
        if not normalized or normalized in seen:
            continue
        seen.add(normalized)
        ordered.append(normalized)
    return tuple(ordered)


class AuthzError(RuntimeError):
    """Base error for authorization bootstrap helpers."""

    status_code = 500

    def __init__(self, detail: str) -> None:
        super().__init__(detail)
        self.detail = detail


class UnauthenticatedError(AuthzError):
    """Raised when a caller has no authenticated identity."""

    status_code = 401


class ForbiddenError(AuthzError):
    """Raised when a caller lacks required authorization."""

    status_code = 403


@dataclass(frozen=True, slots=True)
class AuthenticatedPrincipal:
    """
    Normalized authenticated identity shared across backend slices.

    The model deliberately keeps only a compact set of commonly-used fields
    while still preserving the upstream raw claims for application-specific use.
    """

    subject: str
    roles: tuple[str, ...] = ()
    scopes: tuple[str, ...] = ()
    issuer: str | None = None
    audience: tuple[str, ...] = ()
    email: str | None = None
    name: str | None = None
    tenant_id: str | None = None
    client_id: str | None = None
    auth_time: int | None = None
    raw_claims: Mapping[str, Any] = field(default_factory=dict, repr=False)

    def __post_init__(self) -> None:
        subject = self.subject.strip()
        if not subject:
            raise ValueError("AuthenticatedPrincipal.subject must not be empty")

        object.__setattr__(self, "subject", subject)
        object.__setattr__(self, "roles", _dedupe_strings(tuple(self.roles)))
        object.__setattr__(self, "scopes", _dedupe_strings(tuple(self.scopes)))
        object.__setattr__(self, "audience", _dedupe_strings(tuple(self.audience)))
        object.__setattr__(self, "raw_claims", dict(self.raw_claims))

    def has_role(self, role: str, *, case_sensitive: bool = False) -> bool:
        if not role.strip():
            return False
        if case_sensitive:
            return role in self.roles
        lowered = role.casefold()
        return any(existing.casefold() == lowered for existing in self.roles)

    def has_any_role(self, *roles: str, case_sensitive: bool = False) -> bool:
        return any(self.has_role(role, case_sensitive=case_sensitive) for role in roles)

    def has_all_roles(self, *roles: str, case_sensitive: bool = False) -> bool:
        meaningful = [role for role in roles if role.strip()]
        return all(self.has_role(role, case_sensitive=case_sensitive) for role in meaningful)

    def has_scope(self, scope: str, *, case_sensitive: bool = False) -> bool:
        if not scope.strip():
            return False
        if case_sensitive:
            return scope in self.scopes
        lowered = scope.casefold()
        return any(existing.casefold() == lowered for existing in self.scopes)

    def has_any_scope(self, *scopes: str, case_sensitive: bool = False) -> bool:
        return any(self.has_scope(scope, case_sensitive=case_sensitive) for scope in scopes)

    def to_log_dict(self) -> dict[str, Any]:
        """
        Return a compact structured-logging representation.

        PII-heavy attributes such as email, display name, and raw claims are
        intentionally excluded to support log minimization by default.
        """
        payload: dict[str, Any] = {
            "subject": self.subject,
            "roles": list(self.roles),
            "scopes": list(self.scopes),
        }
        if self.issuer:
            payload["issuer"] = self.issuer
        if self.audience:
            payload["audience"] = list(self.audience)
        if self.tenant_id:
            payload["tenant_id"] = self.tenant_id
        if self.client_id:
            payload["client_id"] = self.client_id
        if self.auth_time is not None:
            payload["auth_time"] = self.auth_time
        return payload
