from __future__ import annotations

import json
from types import SimpleNamespace
from typing import Any, Mapping, Protocol

from .claims import build_principal_from_claims
from .models import AuthenticatedPrincipal, ForbiddenError, UnauthenticatedError
from .settings import AuthzSettings, load_authz_settings

try:
    from fastapi import HTTPException
except Exception:  # pragma: no cover - fallback for minimal test environments
    class HTTPException(Exception):
        def __init__(self, status_code: int, detail: str) -> None:
            super().__init__(detail)
            self.status_code = status_code
            self.detail = detail


class RequestLike(Protocol):
    state: Any
    scope: Mapping[str, Any]
    headers: Mapping[str, str]


def _http_exception_from_authz_error(error: Exception) -> HTTPException:
    status_code = getattr(error, "status_code", 500)
    detail = getattr(error, "detail", str(error))
    return HTTPException(status_code=status_code, detail=detail)


def _state_value(request: RequestLike, name: str) -> Any:
    state = getattr(request, "state", None)
    if state is None:
        return None
    if isinstance(state, Mapping):
        return state.get(name)
    return getattr(state, name, None)


def extract_request_claims(request: RequestLike) -> Mapping[str, Any]:
    """
    Read already-authenticated claims from common framework injection points.

    Search order prefers explicit request state over scope, and falls back to a
    JSON-encoded diagnostic header for local development or proxy integration.
    """
    candidates = (
        _state_value(request, "auth_claims"),
        _state_value(request, "claims"),
        request.scope.get("auth", {}).get("claims") if isinstance(request.scope.get("auth"), Mapping) else None,
        request.scope.get("claims"),
    )

    for candidate in candidates:
        if isinstance(candidate, Mapping):
            return dict(candidate)

    header_value = request.headers.get("x-auth-request-claims")
    if header_value:
        try:
            parsed = json.loads(header_value)
        except json.JSONDecodeError as exc:
            raise UnauthenticatedError("Invalid x-auth-request-claims header payload") from exc
        if not isinstance(parsed, Mapping):
            raise UnauthenticatedError("x-auth-request-claims header must decode to an object")
        return dict(parsed)

    return {}


def enforce_roles(
    principal: AuthenticatedPrincipal,
    required_roles: tuple[str, ...] | list[str],
    *,
    require_all: bool = False,
    settings: AuthzSettings | None = None,
    allow_admin_override: bool = True,
) -> AuthenticatedPrincipal:
    normalized_required = tuple(role.strip() for role in required_roles if role and role.strip())
    if not normalized_required:
        return principal

    resolved_settings = settings or AuthzSettings()

    if allow_admin_override and principal.has_any_role(*resolved_settings.admin_roles):
        return principal

    authorized = (
        principal.has_all_roles(*normalized_required)
        if require_all
        else principal.has_any_role(*normalized_required)
    )
    if not authorized:
        raise ForbiddenError(
            f"Principal '{principal.subject}' lacks required role(s): {', '.join(normalized_required)}"
        )
    return principal


def resolve_current_principal(
    claims: Mapping[str, Any] | None,
    settings: AuthzSettings | None = None,
) -> AuthenticatedPrincipal:
    resolved_settings = settings or AuthzSettings()
    principal = build_principal_from_claims(claims, settings=resolved_settings)
    return enforce_roles(
        principal,
        resolved_settings.required_roles,
        require_all=False,
        settings=resolved_settings,
    )


def get_current_principal(
    request: RequestLike,
    settings: AuthzSettings | None = None,
) -> AuthenticatedPrincipal:
    resolved_settings = settings or load_authz_settings()
    try:
        claims = extract_request_claims(request)
        return resolve_current_principal(claims, settings=resolved_settings)
    except (UnauthenticatedError, ForbiddenError) as error:
        raise _http_exception_from_authz_error(error) from error


def require_roles(
    *roles: str,
    require_all: bool = False,
    settings: AuthzSettings | None = None,
    allow_admin_override: bool = True,
):
    resolved_required_roles = tuple(role for role in roles if role and role.strip())

    def dependency(request: RequestLike) -> AuthenticatedPrincipal:
        resolved_settings = settings or load_authz_settings()
        principal = get_current_principal(request, settings=resolved_settings)
        return enforce_roles(
            principal,
            resolved_required_roles,
            require_all=require_all,
            settings=resolved_settings,
            allow_admin_override=allow_admin_override,
        )

    return dependency


def make_request_like(
    *,
    claims: Mapping[str, Any] | None = None,
    headers: Mapping[str, str] | None = None,
) -> RequestLike:
    """
    Test-friendly helper mirroring the framework contract used by this module.
    """
    return SimpleNamespace(
        state=SimpleNamespace(auth_claims=dict(claims or {})),
        scope={},
        headers=dict(headers or {}),
    )
