from __future__ import annotations

import json
import os
from dataclasses import dataclass
from typing import Iterable, Mapping


def _dedupe(values: Iterable[str]) -> tuple[str, ...]:
    seen: set[str] = set()
    ordered: list[str] = []
    for value in values:
        normalized = str(value).strip()
        if not normalized or normalized in seen:
            continue
        seen.add(normalized)
        ordered.append(normalized)
    return tuple(ordered)


def _parse_bool(raw: object, *, default: bool) -> bool:
    if raw is None:
        return default
    if isinstance(raw, bool):
        return raw
    normalized = str(raw).strip().casefold()
    if normalized in {"1", "true", "t", "yes", "y", "on"}:
        return True
    if normalized in {"0", "false", "f", "no", "n", "off"}:
        return False
    raise ValueError(f"Invalid boolean value: {raw!r}")


def _parse_str(raw: object, *, default: str) -> str:
    if raw is None:
        return default
    value = str(raw).strip()
    return value or default


def _parse_name_list(raw: object, *, default: tuple[str, ...]) -> tuple[str, ...]:
    if raw is None:
        return default
    if isinstance(raw, (list, tuple, set)):
        return _dedupe(str(item) for item in raw)

    text = str(raw).strip()
    if not text:
        return default

    if text.startswith("["):
        decoded = json.loads(text)
        if not isinstance(decoded, list):
            raise ValueError(f"Expected a JSON array, got: {raw!r}")
        return _dedupe(str(item) for item in decoded)

    parts = [segment.strip() for chunk in text.split(",") for segment in chunk.splitlines()]
    return _dedupe(parts)


@dataclass(frozen=True, slots=True)
class AuthzSettings:
    """
    Shared authorization normalization settings.

    These settings deliberately focus on claim extraction, RBAC enforcement,
    and secure logging behavior. Token verification and IdP-specific wiring
    remain outside this REQ boundary.
    """

    enabled: bool = True
    allow_unauthenticated: bool = False
    unauthenticated_subject: str = "anonymous"
    unauthenticated_roles: tuple[str, ...] = ()

    principal_claim_names: tuple[str, ...] = (
        "sub",
        "preferred_username",
        "email",
        "client_id",
    )
    role_claim_names: tuple[str, ...] = (
        "roles",
        "groups",
        "realm_access.roles",
        "cognito:groups",
    )
    scope_claim_names: tuple[str, ...] = ("scope", "scp")
    audience_claim_names: tuple[str, ...] = ("aud",)
    tenant_claim_names: tuple[str, ...] = ("tenant_id", "tenant", "org_id")
    email_claim_names: tuple[str, ...] = ("email",)
    name_claim_names: tuple[str, ...] = ("name", "preferred_username")
    issuer_claim_names: tuple[str, ...] = ("iss",)
    client_id_claim_names: tuple[str, ...] = ("client_id", "azp")

    required_roles: tuple[str, ...] = ()
    admin_roles: tuple[str, ...] = ("admin", "platform-admin")

    redact_claim_keys: tuple[str, ...] = (
        "access_token",
        "refresh_token",
        "id_token",
        "authorization",
        "cookie",
        "set-cookie",
        "password",
        "secret",
        "client_secret",
        "assertion",
        "credentials",
    )

    def __post_init__(self) -> None:
        object.__setattr__(self, "principal_claim_names", _dedupe(self.principal_claim_names))
        object.__setattr__(self, "role_claim_names", _dedupe(self.role_claim_names))
        object.__setattr__(self, "scope_claim_names", _dedupe(self.scope_claim_names))
        object.__setattr__(self, "audience_claim_names", _dedupe(self.audience_claim_names))
        object.__setattr__(self, "tenant_claim_names", _dedupe(self.tenant_claim_names))
        object.__setattr__(self, "email_claim_names", _dedupe(self.email_claim_names))
        object.__setattr__(self, "name_claim_names", _dedupe(self.name_claim_names))
        object.__setattr__(self, "issuer_claim_names", _dedupe(self.issuer_claim_names))
        object.__setattr__(self, "client_id_claim_names", _dedupe(self.client_id_claim_names))
        object.__setattr__(self, "required_roles", _dedupe(self.required_roles))
        object.__setattr__(self, "admin_roles", _dedupe(self.admin_roles))
        object.__setattr__(self, "unauthenticated_roles", _dedupe(self.unauthenticated_roles))
        object.__setattr__(self, "redact_claim_keys", _dedupe(self.redact_claim_keys))

        if not self.principal_claim_names:
            raise ValueError("principal_claim_names must contain at least one claim name")
        if not self.role_claim_names:
            raise ValueError("role_claim_names must contain at least one claim name")
        if not self.scope_claim_names:
            raise ValueError("scope_claim_names must contain at least one claim name")

        subject = self.unauthenticated_subject.strip()
        if not subject:
            raise ValueError("unauthenticated_subject must not be empty")
        object.__setattr__(self, "unauthenticated_subject", subject)

    @classmethod
    def from_mapping(
        cls,
        mapping: Mapping[str, object] | None = None,
        *,
        prefix: str = "AUTHZ_",
    ) -> "AuthzSettings":
        source = mapping or {}

        def read(name: str) -> object | None:
            return source.get(f"{prefix}{name}")

        return cls(
            enabled=_parse_bool(read("ENABLED"), default=True),
            allow_unauthenticated=_parse_bool(read("ALLOW_UNAUTHENTICATED"), default=False),
            unauthenticated_subject=_parse_str(
                read("UNAUTHENTICATED_SUBJECT"),
                default="anonymous",
            ),
            unauthenticated_roles=_parse_name_list(
                read("UNAUTHENTICATED_ROLES"),
                default=(),
            ),
            principal_claim_names=_parse_name_list(
                read("PRINCIPAL_CLAIM_NAMES"),
                default=cls.principal_claim_names,
            ),
            role_claim_names=_parse_name_list(
                read("ROLE_CLAIM_NAMES"),
                default=cls.role_claim_names,
            ),
            scope_claim_names=_parse_name_list(
                read("SCOPE_CLAIM_NAMES"),
                default=cls.scope_claim_names,
            ),
            audience_claim_names=_parse_name_list(
                read("AUDIENCE_CLAIM_NAMES"),
                default=cls.audience_claim_names,
            ),
            tenant_claim_names=_parse_name_list(
                read("TENANT_CLAIM_NAMES"),
                default=cls.tenant_claim_names,
            ),
            email_claim_names=_parse_name_list(
                read("EMAIL_CLAIM_NAMES"),
                default=cls.email_claim_names,
            ),
            name_claim_names=_parse_name_list(
                read("NAME_CLAIM_NAMES"),
                default=cls.name_claim_names,
            ),
            issuer_claim_names=_parse_name_list(
                read("ISSUER_CLAIM_NAMES"),
                default=cls.issuer_claim_names,
            ),
            client_id_claim_names=_parse_name_list(
                read("CLIENT_ID_CLAIM_NAMES"),
                default=cls.client_id_claim_names,
            ),
            required_roles=_parse_name_list(
                read("REQUIRED_ROLES"),
                default=(),
            ),
            admin_roles=_parse_name_list(
                read("ADMIN_ROLES"),
                default=cls.admin_roles,
            ),
            redact_claim_keys=_parse_name_list(
                read("REDACT_CLAIM_KEYS"),
                default=cls.redact_claim_keys,
            ),
        )

    @classmethod
    def from_env(
        cls,
        environ: Mapping[str, str] | None = None,
        *,
        prefix: str = "AUTHZ_",
    ) -> "AuthzSettings":
        return cls.from_mapping(environ or os.environ, prefix=prefix)


def load_authz_settings(
    mapping: Mapping[str, object] | None = None,
    *,
    prefix: str = "AUTHZ_",
) -> AuthzSettings:
    if mapping is None:
        return AuthzSettings.from_env(prefix=prefix)
    return AuthzSettings.from_mapping(mapping, prefix=prefix)
