from __future__ import annotations

import re
from typing import Any, Iterable, Mapping

from .models import AuthenticatedPrincipal, UnauthenticatedError
from .settings import AuthzSettings

_WHITESPACE_OR_COMMA = re.compile(r"[\s,]+")


def _dedupe(values: Iterable[str]) -> tuple[str, ...]:
    seen: set[str] = set()
    ordered: list[str] = []
    for value in values:
        normalized = value.strip()
        if not normalized or normalized in seen:
            continue
        seen.add(normalized)
        ordered.append(normalized)
    return tuple(ordered)


def claim_lookup(claims: Mapping[str, Any], path: str) -> Any:
    """
    Resolve a claim by exact key first, then by dotted nested path.
    """
    if path in claims:
        return claims[path]

    current: Any = claims
    for segment in path.split("."):
        if not isinstance(current, Mapping) or segment not in current:
            return None
        current = current[segment]
    return current


def _coerce_scalar(value: Any) -> str | None:
    if value is None:
        return None
    if isinstance(value, str):
        normalized = value.strip()
        return normalized or None
    return str(value).strip() or None


def _flatten_values(value: Any, *, split_tokens: bool) -> tuple[str, ...]:
    if value is None:
        return ()

    if isinstance(value, str):
        text = value.strip()
        if not text:
            return ()
        if split_tokens:
            return _dedupe(token for token in _WHITESPACE_OR_COMMA.split(text) if token)
        if "," in text:
            return _dedupe(token for token in (part.strip() for part in text.split(",")) if token)
        return (text,)

    if isinstance(value, (list, tuple, set, frozenset)):
        flattened: list[str] = []
        for item in value:
            flattened.extend(_flatten_values(item, split_tokens=split_tokens))
        return _dedupe(flattened)

    scalar = _coerce_scalar(value)
    return (scalar,) if scalar else ()


def extract_claim_values(
    claims: Mapping[str, Any],
    candidate_names: Iterable[str],
    *,
    split_tokens: bool = False,
) -> tuple[str, ...]:
    collected: list[str] = []
    for claim_name in candidate_names:
        value = claim_lookup(claims, claim_name)
        collected.extend(_flatten_values(value, split_tokens=split_tokens))
    return _dedupe(collected)


def extract_subject(claims: Mapping[str, Any], settings: AuthzSettings) -> str | None:
    for claim_name in settings.principal_claim_names:
        value = _coerce_scalar(claim_lookup(claims, claim_name))
        if value:
            return value
    return None


def extract_roles(claims: Mapping[str, Any], settings: AuthzSettings) -> tuple[str, ...]:
    return extract_claim_values(claims, settings.role_claim_names, split_tokens=False)


def extract_scopes(claims: Mapping[str, Any], settings: AuthzSettings) -> tuple[str, ...]:
    return extract_claim_values(claims, settings.scope_claim_names, split_tokens=True)


def extract_audience(claims: Mapping[str, Any], settings: AuthzSettings) -> tuple[str, ...]:
    return extract_claim_values(claims, settings.audience_claim_names, split_tokens=False)


def build_principal_from_claims(
    claims: Mapping[str, Any] | None,
    settings: AuthzSettings | None = None,
) -> AuthenticatedPrincipal:
    """
    Normalize upstream identity claims into a stable principal model.

    The caller is expected to provide already-authenticated claims from the
    framework or edge-auth layer. This helper does not verify signatures.
    """
    resolved_settings = settings or AuthzSettings()
    normalized_claims = dict(claims or {})

    if not resolved_settings.enabled:
        return AuthenticatedPrincipal(
            subject=resolved_settings.unauthenticated_subject,
            roles=resolved_settings.unauthenticated_roles,
            raw_claims=normalized_claims,
        )

    subject = extract_subject(normalized_claims, resolved_settings)
    if not subject:
        if resolved_settings.allow_unauthenticated:
            return AuthenticatedPrincipal(
                subject=resolved_settings.unauthenticated_subject,
                roles=resolved_settings.unauthenticated_roles,
                raw_claims=normalized_claims,
            )
        raise UnauthenticatedError("Authenticated subject claim is missing")

    issuer = next(
        (
            value
            for claim_name in resolved_settings.issuer_claim_names
            if (value := _coerce_scalar(claim_lookup(normalized_claims, claim_name)))
        ),
        None,
    )
    email = next(
        (
            value
            for claim_name in resolved_settings.email_claim_names
            if (value := _coerce_scalar(claim_lookup(normalized_claims, claim_name)))
        ),
        None,
    )
    name = next(
        (
            value
            for claim_name in resolved_settings.name_claim_names
            if (value := _coerce_scalar(claim_lookup(normalized_claims, claim_name)))
        ),
        None,
    )
    tenant_id = next(
        (
            value
            for claim_name in resolved_settings.tenant_claim_names
            if (value := _coerce_scalar(claim_lookup(normalized_claims, claim_name)))
        ),
        None,
    )
    client_id = next(
        (
            value
            for claim_name in resolved_settings.client_id_claim_names
            if (value := _coerce_scalar(claim_lookup(normalized_claims, claim_name)))
        ),
        None,
    )

    auth_time_raw = claim_lookup(normalized_claims, "auth_time")
    auth_time = None
    if auth_time_raw is not None:
        try:
            auth_time = int(auth_time_raw)
        except (TypeError, ValueError):
            auth_time = None

    return AuthenticatedPrincipal(
        subject=subject,
        roles=extract_roles(normalized_claims, resolved_settings),
        scopes=extract_scopes(normalized_claims, resolved_settings),
        issuer=issuer,
        audience=extract_audience(normalized_claims, resolved_settings),
        email=email,
        name=name,
        tenant_id=tenant_id,
        client_id=client_id,
        auth_time=auth_time,
        raw_claims=normalized_claims,
    )


def principal_from_claims(
    claims: Mapping[str, Any] | None,
    settings: AuthzSettings | None = None,
) -> AuthenticatedPrincipal:
    return build_principal_from_claims(claims, settings=settings)
