from __future__ import annotations

from typing import Any, Mapping

from .models import AuthenticatedPrincipal
from .settings import AuthzSettings

_SENSITIVE_KEY_FRAGMENTS = (
    "token",
    "secret",
    "password",
    "cookie",
    "credential",
    "authorization",
    "assertion",
)


def _is_sensitive_key(key: str, settings: AuthzSettings) -> bool:
    lowered = key.casefold()
    explicit = {name.casefold() for name in settings.redact_claim_keys}
    if lowered in explicit:
        return True
    return any(fragment in lowered for fragment in _SENSITIVE_KEY_FRAGMENTS)


def sanitize_claims_for_logging(
    value: Any,
    settings: AuthzSettings | None = None,
) -> Any:
    resolved_settings = settings or AuthzSettings()

    if isinstance(value, Mapping):
        sanitized: dict[str, Any] = {}
        for key, nested_value in value.items():
            key_text = str(key)
            if _is_sensitive_key(key_text, resolved_settings):
                sanitized[key_text] = "[REDACTED]"
            else:
                sanitized[key_text] = sanitize_claims_for_logging(
                    nested_value,
                    settings=resolved_settings,
                )
        return sanitized

    if isinstance(value, (list, tuple, set, frozenset)):
        return [sanitize_claims_for_logging(item, settings=resolved_settings) for item in value]

    return value


def format_authz_log_fields(
    principal: AuthenticatedPrincipal | None = None,
    *,
    decision: str | None = None,
    reason: str | None = None,
    claims: Mapping[str, Any] | None = None,
    settings: AuthzSettings | None = None,
    **extra: Any,
) -> dict[str, Any]:
    """
    Produce structured logging fields that are safe to attach to application logs.
    """
    fields: dict[str, Any] = {}
    if decision:
        fields["authz_decision"] = decision
    if reason:
        fields["authz_reason"] = reason
    if principal is not None:
        fields["authz_principal"] = principal.to_log_dict()
    if claims is not None:
        fields["authz_claims"] = sanitize_claims_for_logging(
            claims,
            settings=settings or AuthzSettings(),
        )
    if extra:
        fields.update(extra)
    return fields


def build_authz_log_fields(
    principal: AuthenticatedPrincipal | None = None,
    *,
    decision: str | None = None,
    reason: str | None = None,
    claims: Mapping[str, Any] | None = None,
    settings: AuthzSettings | None = None,
    **extra: Any,
) -> dict[str, Any]:
    return format_authz_log_fields(
        principal,
        decision=decision,
        reason=reason,
        claims=claims,
        settings=settings,
        **extra,
    )
