from __future__ import annotations

from backend.shared.authz.logging import format_authz_log_fields, sanitize_claims_for_logging
from backend.shared.authz.models import AuthenticatedPrincipal
from backend.shared.authz.settings import AuthzSettings


def test_sanitize_claims_for_logging_redacts_nested_sensitive_fields() -> None:
    claims = {
        "sub": "alice",
        "email": "alice@example.com",
        "authorization": "Bearer top-secret",
        "nested": {
            "refresh_token": "refresh-me",
            "profile": {"department": "finance"},
        },
        "cookies": [{"session_cookie": "abc123"}],
    }

    sanitized = sanitize_claims_for_logging(claims)

    assert sanitized["sub"] == "alice"
    assert sanitized["email"] == "alice@example.com"
    assert sanitized["authorization"] == "[REDACTED]"
    assert sanitized["nested"]["refresh_token"] == "[REDACTED]"
    assert sanitized["nested"]["profile"]["department"] == "finance"
    assert sanitized["cookies"][0]["session_cookie"] == "[REDACTED]"


def test_sanitize_claims_for_logging_honors_explicit_custom_redaction_keys() -> None:
    settings = AuthzSettings(redact_claim_keys=("api_key",))
    claims = {"api_key": "12345", "safe": "value"}

    sanitized = sanitize_claims_for_logging(claims, settings=settings)

    assert sanitized == {"api_key": "[REDACTED]", "safe": "value"}


def test_format_authz_log_fields_keeps_operational_context_and_minimizes_pii() -> None:
    principal = AuthenticatedPrincipal(
        subject="alice",
        roles=("reviewer",),
        scopes=("documents:read",),
        email="alice@example.com",
        name="Alice Example",
        tenant_id="tenant-a",
        raw_claims={"email": "alice@example.com"},
    )

    fields = format_authz_log_fields(
        principal,
        decision="allow",
        reason="role-match",
        claims={"sub": "alice", "access_token": "secret"},
        document_id="doc-123",
    )

    assert fields["authz_decision"] == "allow"
    assert fields["authz_reason"] == "role-match"
    assert fields["document_id"] == "doc-123"
    assert fields["authz_principal"]["subject"] == "alice"
    assert fields["authz_principal"]["roles"] == ["reviewer"]
    assert "email" not in fields["authz_principal"]
    assert "name" not in fields["authz_principal"]
    assert fields["authz_claims"]["access_token"] == "[REDACTED]"
